"""Conventional fixedwing guidance using only own-aircraft navigation state.

PyFlyt uses an ENU world and body x forward, y left, z up. Positive pitch is
nose down; positive roll banks right. Commands address mode -1 surfaces
explicitly, avoiding the upstream mode 0 tail-surface coupling.
"""

from __future__ import annotations

from dataclasses import dataclass
import math

import numpy as np


def wrap_angle(angle: float) -> float:
    return (angle + math.pi) % (2.0 * math.pi) - math.pi


@dataclass(frozen=True)
class FlightTarget:
    heading: float
    altitude: float = 80.0
    airspeed: float = 20.0
    bank_feedforward: float = 0.0

    def __post_init__(self) -> None:
        if not all(math.isfinite(x) for x in (
            self.heading, self.altitude, self.airspeed, self.bank_feedforward
        )) or self.altitude <= 0.0 or self.airspeed <= 0.0:
            raise ValueError("flight target must be finite with positive altitude and airspeed")


@dataclass(frozen=True)
class ControlGains:
    heading_p: float = 0.8
    roll_p: float = 1.5
    roll_d: float = 0.3
    pitch_p: float = 1.5
    pitch_d: float = 0.4
    altitude_p: float = 0.3
    altitude_i: float = 0.015
    speed_p: float = 0.08
    speed_i: float = 0.015
    pitch_trim: float = -0.04
    elevator_trim: float = -0.03
    throttle_trim: float = 0.4
    altitude_throttle_p: float = 0.0
    max_vertical_speed: float | None = None
    max_bank: float = math.radians(30.0)
    max_pitch: float = math.radians(12.0)


class FixedwingAutopilot:
    """Nested PI/PD loops, shared by every prospective mission policy."""

    def __init__(self, gains: ControlGains | None = None):
        self.gains = gains or ControlGains()
        self.altitude_integral = 0.0
        self.speed_integral = 0.0

    def step(self, state: np.ndarray, target: FlightTarget, dt: float,
             measured_airspeed: float | None = None) -> np.ndarray:
        if state.shape != (4, 3) or not np.isfinite(state).all():
            raise ValueError("navigation state must be a finite (4, 3) array")
        if not math.isfinite(dt) or dt <= 0.0:
            raise ValueError("dt must be finite and positive")
        rates, attitude, velocity, position = state
        roll, pitch, heading = attitude
        g = self.gains
        speed = float(np.linalg.norm(velocity)) if measured_airspeed is None else measured_airspeed
        if not math.isfinite(speed) or speed < 0:
            raise ValueError("measured airspeed must be finite and nonnegative")
        height_error = target.altitude - position[2]
        speed_error = target.airspeed - speed
        proposed_integral = float(np.clip(self.altitude_integral + height_error * dt, -20.0, 20.0))
        proposed_vertical = g.altitude_p*height_error+g.altitude_i*proposed_integral
        saturated = (g.max_vertical_speed is not None and abs(proposed_vertical) > g.max_vertical_speed
                     and height_error*proposed_vertical > 0)
        if not saturated:
            self.altitude_integral = proposed_integral
        self.speed_integral = float(np.clip(self.speed_integral + speed_error * dt, -15.0, 15.0))
        bank = float(np.clip(
            -g.heading_p * wrap_angle(target.heading - heading) + target.bank_feedforward,
            -g.max_bank, g.max_bank,
        ))
        vertical_command = g.altitude_p*height_error+g.altitude_i*self.altitude_integral
        if g.max_vertical_speed is not None:
            vertical_command = float(np.clip(vertical_command,-g.max_vertical_speed,g.max_vertical_speed))
        pitch_target = float(np.clip(
            g.pitch_trim - math.atan2(vertical_command, max(speed, 5.0)),
            -g.max_pitch, g.max_pitch,
        ))
        aileron = float(np.clip(g.roll_p * (bank - roll) - g.roll_d * rates[0], -1.0, 1.0))
        elevator = float(np.clip(g.elevator_trim + g.pitch_p * (pitch_target - pitch) - g.pitch_d * rates[1], -1.0, 1.0))
        turn_rate = -9.81 * math.tan(bank) / max(speed, 5.0)
        rudder = float(np.clip(0.4 * (rates[2] - turn_rate * math.cos(roll)), -0.5, 0.5))
        throttle = float(np.clip(g.throttle_trim + g.speed_p * speed_error + g.speed_i * self.speed_integral
                                 + g.altitude_throttle_p * height_error, 0.0, 1.0))
        return np.array([aileron, -aileron, elevator, rudder, 0.0, throttle])


def inspection_gains():
    """Development profile with bounded vertical command and anti-windup.

    The1.2 value limits the desired vertical command, not measured climb rate.
    It requires new qualification; legacy ControlGains defaults are retained.
    """
    return ControlGains(pitch_p=4.5,pitch_trim=-.07,elevator_trim=-.1,speed_p=.12,max_vertical_speed=1.2)


def orbit_target(position: np.ndarray, center: np.ndarray, radius: float, altitude: float = 80.0,
                 airspeed: float = 20.0, direction: int = 1) -> FlightTarget:
    """Tangent vector field; direction +1 is counterclockwise in ENU."""
    if radius <= 0.0 or not math.isfinite(radius) or direction not in (-1, 1):
        raise ValueError("radius must be positive and direction must be +/-1")
    offset = position[:2] - center[:2]
    distance = float(np.linalg.norm(offset))
    radial = math.atan2(offset[1], offset[0])
    heading = radial + direction * (math.pi / 2.0 + math.atan(2.0 * (distance - radius) / radius))
    feedforward = -direction * math.atan2(airspeed ** 2, 9.81 * radius)
    return FlightTarget(heading, altitude, airspeed, feedforward)


def air_heading_for_course(course: float, wind_xy: np.ndarray, airspeed: float) -> float:
    """Crab correction from shared ideal local airdata; no mission truth input."""
    if wind_xy.shape != (2,) or not np.isfinite(wind_xy).all() or not math.isfinite(airspeed) or airspeed <= 0:
        raise ValueError("finite planar wind and positive airspeed required")
    crosswind = -wind_xy[0] * math.sin(course) + wind_xy[1] * math.cos(course)
    if abs(crosswind) >= airspeed:
        raise ValueError("requested course is infeasible in this crosswind")
    return wrap_angle(course - math.asin(crosswind / airspeed))


class SurveyRoute:
    """Counterclockwise capsule with physical semicircle transitions."""

    def __init__(self, center_y: float, half_length: float = 250.0, radius: float = 80.0):
        self.center_y, self.half_length, self.radius = center_y, half_length, radius
        self.leg = "bottom"
        self.laps = 0

    def target(self, position: np.ndarray, altitude: float, airspeed: float = 20.) -> FlightTarget:
        x, y = position[:2]
        if self.leg == "bottom" and x >= self.half_length:
            self.leg = "right"
        elif self.leg == "right" and x <= self.half_length + 5 and y > self.center_y + 20:
            self.leg = "top"
        elif self.leg == "top" and x <= -self.half_length:
            self.leg = "left"
        elif self.leg == "left" and x >= -self.half_length - 5 and y < self.center_y - 20:
            self.leg = "bottom"
            self.laps += 1
        if self.leg in ("right", "left"):
            center = np.array([self.half_length if self.leg == "right" else -self.half_length, self.center_y])
            return orbit_target(position, center, self.radius, altitude,airspeed)
        desired_y = self.center_y + (self.radius if self.leg == "top" else -self.radius)
        return FlightTarget(math.atan2(desired_y-y, -80 if self.leg == "top" else 80), altitude,airspeed)

    def cross_track_error(self, position: np.ndarray) -> float:
        x, y = position[:2]
        if abs(x) <= self.half_length:
            return min(abs(y-self.center_y-self.radius), abs(y-self.center_y+self.radius))
        return abs(math.hypot(abs(x)-self.half_length, y-self.center_y)-self.radius)

"""Finite analytic forward paths, usable in a planning process without PyFlyt.

No mission, generator, evidence or grader imports. Geometry is not a physical
certificate: measured tracking tubes must be supplied by qualification.
"""

from __future__ import annotations

from dataclasses import dataclass
import math

import numpy as np

from envs.inspection.control import FlightTarget, wrap_angle


@dataclass(frozen=True)
class Pose:
    x: float
    y: float
    heading: float

    def __post_init__(self):
        if not all(math.isfinite(x) for x in (self.x, self.y, self.heading)):
            raise ValueError("finite pose required")


@dataclass(frozen=True)
class Primitive:
    start: Pose
    length: float
    curvature: float

    def __post_init__(self):
        if not all(math.isfinite(x) for x in (*self.start.__dict__.values(), self.length, self.curvature)) or self.length < 0:
            raise ValueError("finite forward primitive required")

    def pose(self, distance):
        if not math.isfinite(distance) or not -1e-8 <= distance <= self.length+1e-8:
            raise ValueError("distance outside primitive")
        s = max(0., min(self.length, distance))
        p, k = self.start, self.curvature
        h = p.heading+k*s
        if abs(k) < 1e-12:
            return Pose(p.x+s*math.cos(h), p.y+s*math.sin(h), h)
        return Pose(p.x+(math.sin(h)-math.sin(p.heading))/k,
                    p.y+(-math.cos(h)+math.cos(p.heading))/k, h)

    @property
    def end(self):
        return self.pose(self.length)


def primitives(start, pieces):
    result = []
    for curvature, length in pieces:
        if length < 1e-8:
            continue
        result.append(Primitive(start, length, curvature))
        start = result[-1].end
    return tuple(result)


def stripe_transfer(start, destination_y, radius=100.):
    """Two quarter arcs; start must be an eastbound bottom-leg port.

    destination_y is the bottom-leg coordinate, not the stripe center.
    """
    if abs(wrap_angle(start.heading)) > 1e-6 or abs(destination_y-start.y) < 2*radius-1e-8 or radius <= 0:
        raise ValueError("eastbound port and sufficient lateral displacement required")
    sign = math.copysign(1., destination_y-start.y)
    return primitives(start, [(sign/radius, math.pi*radius/2),
                              (0., abs(destination_y-start.y)-2*radius),
                              (-sign/radius, math.pi*radius/2)])


def csc_connectors(start, finish, radius=100.):
    """All four forward circle-straight-circle common-tangent candidates.

    This finite set does not claim to cover every Dubins shortest path.
    Includes longer turns up to2pi, excludes infeasible internal tangents.
    """
    if not math.isfinite(radius) or radius <= 0:
        raise ValueError("positive finite radius required")
    left = lambda h: np.array([-math.sin(h), math.cos(h)])
    candidates = []
    for first in (-1, 1):
        for last in (-1, 1):
            c0 = np.array([start.x, start.y])+first*radius*left(start.heading)
            c1 = np.array([finish.x, finish.y])+last*radius*left(finish.heading)
            delta = c1-c0
            distance = float(np.linalg.norm(delta))
            shift = (first-last)*radius
            if distance < abs(shift)+1e-8 or distance < 1e-8:
                continue
            heading = math.atan2(delta[1], delta[0])+math.asin(shift/distance)
            angle0 = (first*(heading-start.heading)) % (2*math.pi)
            angle1 = (last*(finish.heading-heading)) % (2*math.pi)
            path = primitives(start, [(first/radius, radius*angle0),
                                      (0., math.sqrt(max(0., distance*distance-shift*shift))),
                                      (last/radius, radius*angle1)])
            if not path or math.dist((path[-1].end.x, path[-1].end.y), (finish.x, finish.y)) > 1e-6:
                raise ArithmeticError("connector endpoint derivation failed")
            candidates.append(path)
    return tuple(sorted(candidates, key=lambda p: sum(s.length for s in p)))


def capsule_from_bottom(start, center_y, *, half_length=250., radius=80., laps=1):
    if abs(wrap_angle(start.heading)) > 1e-6 or abs(start.y-(center_y-radius)) > 1e-6 or not -half_length-1e-6 <= start.x <= half_length:
        raise ValueError("capsule entry must lie on its eastbound bottom leg")
    if laps < 1 or isinstance(laps, bool) or not isinstance(laps, int):
        raise ValueError("positive integer laps required")
    pieces = [(0., half_length-start.x), (1/radius, math.pi*radius),
              (0., 2*half_length), (1/radius, math.pi*radius), (0., start.x+half_length)]*laps
    return primitives(start, pieces)


def course_kinematics(course, curvature, wind, airspeed):
    tangent = np.array([math.cos(course), math.sin(course)])
    normal = np.array([-tangent[1], tangent[0]])
    parallel, cross = float(wind@tangent), float(wind@normal)
    if abs(cross) >= airspeed:
        raise ValueError("path infeasible in crosswind")
    q = math.sqrt(airspeed*airspeed-cross*cross)
    ground_speed = parallel+q
    if ground_speed <= 0:
        raise ValueError("path cannot progress forward")
    derivative = cross*(1+parallel/q)
    acceleration = derivative*curvature*ground_speed*tangent+ground_speed**2*curvature*normal
    air_velocity = ground_speed*tangent-wind
    yaw_rate = float(air_velocity[0]*acceleration[1]-air_velocity[1]*acceleration[0])/(airspeed*airspeed)
    return ground_speed, -math.atan(airspeed*yaw_rate/9.81)


class TimedPath:
    """Bounded time sampling done by the planner; tick lookup is O(log N).

    The follower controls longitudinal phase as well as cross-track error.
    Sample timing is a numerical prediction, not a promise of tracking error.
    """

    def __init__(self, path, wind=(0., 0.), airspeed=20., dt=.05):
        if (not path or len(path) > 64 or not math.isfinite(dt) or dt <= 0
                or not math.isfinite(airspeed) or airspeed <= 0 or sum(p.length for p in path) <= 0):
            raise ValueError("bounded nonempty path and positive time/speed required")
        for a,b in zip(path,path[1:]):
            if (math.dist((a.end.x,a.end.y),(b.start.x,b.start.y)) > 1e-7
                    or abs(wrap_angle(a.end.heading-b.start.heading)) > 1e-7):
                raise ValueError("adjacent primitives must be spatially and tangentially continuous")
        self.path = tuple(path)
        self.wind = np.array(wind, dtype=float)
        if self.wind.shape != (2,) or not np.isfinite(self.wind).all():
            raise ValueError("finite planar wind required")
        self.airspeed = airspeed
        rows, stamp = [], 0.
        for primitive in self.path:
            distance = 0.
            while distance < primitive.length-1e-9:
                pose = primitive.pose(distance)
                speed, bank = course_kinematics(pose.heading, primitive.curvature, self.wind, airspeed)
                rows.append((stamp, pose.x, pose.y, pose.heading, speed, bank))
                step = min(dt, (primitive.length-distance)/speed)
                # Midpoint quadrature for changing wind projection on arcs.
                midpoint = primitive.pose(min(primitive.length, distance+speed*step/2))
                middle_speed, _ = course_kinematics(midpoint.heading, primitive.curvature, self.wind, airspeed)
                step = min(step, (primitive.length-distance)/middle_speed)
                distance = min(primitive.length, distance+middle_speed*step)
                stamp += step
                if len(rows) > 60000:
                    raise ValueError("path exceeds bounded planner sample count")
        end = self.path[-1].end
        speed, bank = course_kinematics(end.heading, self.path[-1].curvature, self.wind, airspeed)
        rows.append((stamp, end.x, end.y, end.heading, speed, bank))
        self.samples = np.array(rows)
        self.samples[:, 3] = np.unwrap(self.samples[:, 3])
        self.samples.flags.writeable = False
        self.duration = stamp

    @classmethod
    def from_samples(cls, rows, wind, airspeed=18.):
        samples = np.asarray(rows, dtype=float)
        if (samples.ndim != 2 or samples.shape[1] != 6 or not 2 <= len(samples) <= 16000
                or not np.isfinite(samples).all() or abs(samples[0,0]) > 1e-8
                or not np.all(np.diff(samples[:,0]) > 0)):
            raise ValueError("bounded finite strictly timed samples required")
        result = object.__new__(cls)
        result.samples = samples.copy()
        result.samples[:,3] = np.unwrap(result.samples[:,3])
        result.samples.flags.writeable = False
        result.wind = np.asarray(wind,dtype=float).copy()
        if result.wind.shape != (2,) or not np.isfinite(result.wind).all():
            raise ValueError("finite planar wind required")
        result.airspeed = airspeed
        result.duration = float(samples[-1,0])
        result.path = ()
        return result

    @classmethod
    def concatenate(cls, paths):
        paths = tuple(paths)
        if not paths:
            raise ValueError("nonempty path sequence required")
        rows, stamp = [], 0.
        for i,p in enumerate(paths):
            if not np.array_equal(p.wind,paths[0].wind):
                raise ValueError("concatenated paths require the same wind")
            if i:
                a,b = paths[i-1].at(paths[i-1].duration),p.at(0)
                if np.linalg.norm(a[:2]-b[:2]) > 1e-5 or abs(wrap_angle(a[2]-b[2])) > 1e-5:
                    raise ValueError("continuous concatenation required")
            part = p.samples.copy()
            part[:,0] += stamp
            rows.extend(part[:-1])
            stamp += p.duration
        rows.append(part[-1])
        return cls.from_samples(rows,paths[0].wind,paths[0].airspeed)

    def slice(self, start, finish):
        if not 0 <= start < finish <= self.duration:
            raise ValueError("finite increasing slice inside path required")
        # Avoid duplicate boundary stamps caused by repeated0.05 additions.
        # Keeping a point~1e-15s beside the exact boundary would turn harmless
        # roundoff into an enormous implied interpolation speed.
        middle = self.samples[(self.samples[:,0] > start+1e-8) & (self.samples[:,0] < finish-1e-8)]
        rows = np.vstack((np.r_[start,self.at(start)],middle,np.r_[finish,self.at(finish)]))
        rows[:,0] -= start
        return self.from_samples(rows,self.wind,self.airspeed)

    def at(self, elapsed):
        if not math.isfinite(elapsed) or not 0 <= elapsed <= self.duration+1e-6:
            raise ValueError("path time outside committed interval")
        times = self.samples[:, 0]
        i = max(0, min(len(times)-2, int(np.searchsorted(times, elapsed, side="right")-1)))
        fraction = float(np.clip((elapsed-times[i])/(times[i+1]-times[i]), 0., 1.))
        return self.samples[i, 1:]*(1-fraction)+self.samples[i+1, 1:]*fraction

    def target(self, elapsed, position, altitude, *, measured_airspeed=None):
        return tracking_target(self.at(elapsed), position, altitude, self.wind, measured_airspeed=measured_airspeed)


def tracking_target(sample, position, altitude, wind, *, measured_airspeed=None):
    x, y, heading, speed, bank = sample
    tangent = np.array([math.cos(heading), math.sin(heading)])
    correction = .7*(np.array([x, y])-np.asarray(position)[:2])
    magnitude = float(np.linalg.norm(correction))
    if magnitude > 4:
        correction *= 4/magnitude
    ground_velocity = speed*tangent+correction
    # Lateral steering must not itself accelerate the aircraft. Only along-path
    # phase correction requests speed; turn geometry limits catch-up authority.
    phase_ground = (speed+float(correction@tangent))*tangent
    requested_airspeed = float(np.clip(np.linalg.norm(phase_ground-wind),16.,18.5))
    reference_va = float(np.linalg.norm(speed*tangent-wind))
    _,unit_bank = course_kinematics(heading,1.,wind,reference_va)
    curvature = math.tan(bank)/math.tan(unit_bank)
    if abs(course_kinematics(heading,curvature,wind,requested_airspeed)[1])>math.radians(29):
        low,high = 16.,requested_airspeed
        for _ in range(8):
            middle = (low+high)/2
            if abs(course_kinematics(heading,curvature,wind,middle)[1])<=math.radians(29):low=middle
            else:high=middle
        requested_airspeed=low
    actual_va = reference_va if measured_airspeed is None else float(np.clip(measured_airspeed,15.,25.))
    feedforward = float(np.clip(course_kinematics(heading,curvature,wind,actual_va)[1],
                               -math.radians(29),math.radians(29)))
    return FlightTarget(math.atan2(ground_velocity[1], ground_velocity[0]), altitude, requested_airspeed, feedforward)


@dataclass(frozen=True)
class RouteProgram:
    """Finite prefix with a target-independent periodic physical holding tail."""

    prefix: TimedPath
    tail: TimedPath
    seams: tuple[tuple[float,str],...] = ()

    def __post_init__(self):
        a, b = self.prefix.at(self.prefix.duration), self.tail.at(0)
        end = self.tail.at(self.tail.duration)
        if (np.linalg.norm(a[:2]-b[:2]) > 1e-5 or abs(wrap_angle(a[2]-b[2])) > 1e-5
                or np.linalg.norm(end[:2]-b[:2]) > 1e-5 or abs(wrap_angle(end[2]-b[2])) > 1e-5
                or not np.array_equal(self.prefix.wind, self.tail.wind)):
            raise ValueError("continuous prefix and closed periodic tail required")
        if any(not math.isfinite(t) or not 0<t<=self.prefix.duration+1e-8
               or label not in ("work_end","recovery_start","tail_start") for t,label in self.seams):
            raise ValueError("bounded named physical program seams required")

    def at(self, elapsed):
        if not math.isfinite(elapsed) or elapsed < 0:
            raise ValueError("causal program time required")
        if elapsed < self.prefix.duration:
            return self.prefix.at(elapsed)
        return self.tail.at((elapsed-self.prefix.duration) % self.tail.duration)

    def target(self, elapsed, position, altitude, *, measured_airspeed=None):
        return tracking_target(self.at(elapsed), position, altitude, self.prefix.wind, measured_airspeed=measured_airspeed)

    def xy_at(self, times):
        """Vectorized equivalent of at(t)[:2] for bounded geometry screens."""
        times = np.asarray(times, dtype=float)
        if times.ndim != 1 or not np.isfinite(times).all() or np.any(times < 0):
            raise ValueError("finite causal time vector required")
        prefix = times < self.prefix.duration
        result = np.empty((len(times), 2))
        for mask,path,elapsed in ((prefix,self.prefix,times),
                (~prefix,self.tail,(times-self.prefix.duration) % self.tail.duration)):
            for axis in range(2):
                result[mask,axis] = np.interp(elapsed[mask],path.samples[:,0],path.samples[:,axis+1])
        return result


def fleet_clearance(programs, *, sample_dt=.05):
    if len(programs) != 4 or not math.isfinite(sample_dt) or sample_dt <= 0:
        raise ValueError("exactly four programs and positive sampling interval required")
    for p in programs:
        for path in (p.prefix,p.tail):
            slope = np.linalg.norm(np.diff(path.samples[:,1:3],axis=0),axis=1)/np.diff(path.samples[:,0])
            if not np.isfinite(slope).all() or float(slope.max()) > 27+1e-6:
                raise ValueError("nominal interpolated path exceeds27m/s Lipschitz premise")
    period = programs[0].tail.duration
    if any(abs(p.tail.duration-period) > 1e-6 for p in programs):
        raise ValueError("different tail periods need a different infinite-tail proof")
    # Once all have reached equal-period tails, their joint geometry repeats.
    end = max(p.prefix.duration for p in programs)+period
    times = np.r_[np.arange(0., end, sample_dt), end]
    positions = [p.xy_at(times) for p in programs]
    minimum = min(float(np.linalg.norm(positions[i]-positions[j], axis=1).min())
                  for i in range(4) for j in range(i+1, 4))
    maximum = max(float(np.abs(p).max()) for p in positions)
    return {"sampled_minimum_horizontal_m": minimum, "continuous_lower_bound_horizontal_m": minimum-27*sample_dt,
            "maximum_abs_xy_m_sampled": maximum, "continuous_abs_xy_upper_bound_m": maximum+13.5*sample_dt,
            "checked_seconds": end, "joint_periodic_tail_seconds": period,
            "scope": "complete ideal nominal prefix+periodic-tail geometry; no physical tracking certificate"}

"""Task tools and evaluator-owned evidence. Responses contain no truth verdict."""

from __future__ import annotations

from dataclasses import asdict, dataclass, field
import math
from typing import Callable

from envs.inspection.scoring import GradingMeasurement


def audit_value(value):
    if isinstance(value, float) and not math.isfinite(value):
        return {"invalid_numeric": repr(value)}
    if isinstance(value, dict):
        return {str(k): audit_value(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [audit_value(v) for v in value]
    return value


@dataclass(frozen=True)
class Observation:
    evidence_id: str
    candidate_id: str
    drone_id: int
    measured_at: float
    arrived_at: float
    estimate_xy: tuple[float, float]
    estimated_class: str
    object_type: str
    quality: float
    covariance_xy: tuple[float, float]
    sensor_mode: str
    aircraft_xy: tuple[float, float]
    camera_xyz: tuple[float, float, float] | None = None

    def public(self):
        return asdict(self)


@dataclass(frozen=True)
class Evidence:
    observation: Observation
    entity_key: str | None  # evaluator-only; never serialized to actor


@dataclass
class Report:
    report_id: str
    object_type: str
    associated_key: str | None
    created_at: float
    versions: list[GradingMeasurement] = field(default_factory=list)
    withdrawn: bool = False


class ReportLedger:
    def __init__(self, budget: int, classes: set[str], truth_at: Callable):
        self.budget, self.classes, self.truth_at = budget, classes, truth_at
        self.evidence: dict[str, Evidence] = {}
        self.reports: dict[str, Report] = {}
        self.audit = []
        self.association_ambiguities = 0

    def register(self, evidence: Evidence):
        key = evidence.observation.evidence_id
        if key in self.evidence and self.evidence[key] != evidence:
            raise ValueError("minted evidence is immutable")
        self.evidence[key] = evidence

    def submit(self, request: dict, now: float) -> dict:
        required = {"report_id", "object_type", "candidate_id", "measured_at", "estimate_xy", "claimed_class", "evidence_ids"}
        try:
            if set(request) != required:
                raise ValueError("report schema fields do not match")
            report_id = request["report_id"]
            if not isinstance(report_id, str) or not 1 <= len(report_id) <= 64:
                raise ValueError("invalid report ID")
            if request["object_type"] not in ("static", "dynamic") or request["claimed_class"] not in self.classes:
                raise ValueError("unknown object type or class")
            if not isinstance(request["candidate_id"], str):
                raise ValueError("candidate handle must be a string")
            xy, stamp = request["estimate_xy"], request["measured_at"]
            if not isinstance(xy, (list, tuple)) or len(xy) != 2:
                raise ValueError("planar estimate required")
            if any(isinstance(x, bool) or not isinstance(x, (int, float)) or not math.isfinite(x) for x in (*xy, stamp)):
                raise ValueError("finite numerical estimate and time required")
            ids = request["evidence_ids"]
            if not isinstance(ids, list) or any(not isinstance(i, str) for i in ids) or len(ids) != len(set(ids)):
                raise ValueError("evidence IDs must be a unique string list")
            existing = self.reports.get(report_id)
            if existing and existing.object_type != request["object_type"]:
                raise ValueError("a report cannot change object type")
            if not existing and len(self.reports) >= self.budget:
                raise ValueError("report capacity exhausted")
        except (ValueError, TypeError) as error:
            response = {"status": "rejected", "reason": str(error)}
            self.audit.append(audit_value({"t": now, "request": request, "response": response}))
            return response
        references = [self.evidence[i] for i in ids if i in self.evidence]
        causal = (bool(ids) and len(references) == len(ids) and 0 <= stamp <= now
                  and all(e.observation.measured_at <= stamp and e.observation.arrived_at <= now for e in references)
                  and any(e.observation.measured_at == stamp for e in references))
        if existing is None:
            occupied = {r.associated_key for r in self.reports.values() if r.associated_key is not None}
            matches = []
            if 0 <= stamp <= now:
                for key, position in self.truth_at(stamp).items():
                    distance = math.hypot(xy[0]-position[0], xy[1]-position[1])
                    if distance <= 20 and key not in occupied:
                        matches.append((distance, key))
            matches.sort()
            self.association_ambiguities += int(len(matches) > 1)
            existing = Report(report_id, request["object_type"], matches[0][1] if matches else None, now)
            self.reports[report_id] = existing
        identity_correct = (existing.associated_key is not None and bool(references)
                            and all(e.entity_key == existing.associated_key
                                    and e.observation.candidate_id == request["candidate_id"] for e in references))
        quality_valid = bool(references) and all(e.observation.quality >= .8 for e in references)
        # An invalid/future claim consumes capacity but cannot enter a score.
        safe_stamp = max(0.0, min(float(stamp), now))
        new_evidence_ids = sorted(e.observation.evidence_id for e in references if e.observation.measured_at == stamp)
        measurement_id = new_evidence_ids[0] if new_evidence_ids else "unsupported-"+str(len(existing.versions))
        version = GradingMeasurement(measurement_id, safe_stamp, now, tuple(xy), request["claimed_class"],
                                     identity_correct, quality_valid, causal, len(existing.versions)+1)
        if existing.object_type == "dynamic":
            previous = next((v for v in existing.versions if v.evidence_id == measurement_id), None)
            if previous is not None:
                same = (previous.measured_at == version.measured_at and previous.estimate_xy == version.estimate_xy
                        and previous.claimed_class == version.claimed_class)
                response = {"status": "accepted" if same else "rejected", "report_id": report_id,
                            "reason": "idempotent frozen measurement" if same else "dynamic measurements are sealed"}
                self.audit.append(audit_value({"t": now, "request": request, "response": response}))
                return response
        existing.versions.append(version)
        existing.withdrawn = False
        response = {"status": "accepted", "report_id": report_id,
                    "slots_used": len(self.reports), "slots_remaining": self.budget-len(self.reports)}
        self.audit.append(audit_value({"t": now, "request": request, "response": response}))
        return response

    def withdraw(self, report_id):
        if report_id not in self.reports:
            return {"status": "rejected", "reason": "unknown report"}
        self.reports[report_id].withdrawn = True
        return {"status": "accepted", "slots_used": len(self.reports)}


@dataclass
class Job:
    job_id: str
    drone_id: int
    kind: str
    version: int
    created_at: float
    params: dict
    status: str = "queued"
    started_at: float | None = None
    finished_at: float | None = None
    reason: str | None = None


class JobBook:
    def __init__(self, count):
        self.versions = [0]*count
        self.jobs: dict[str, Job] = {}
        self.active: dict[int, str] = {}
        self.transitions = []

    def create(self, drone_id, kind, params, expected_version, now, *, preempt=False):
        if isinstance(drone_id, bool) or not isinstance(drone_id, int) or not 0 <= drone_id < len(self.versions):
            return {"status": "rejected", "reason": "unknown aircraft"}
        if isinstance(expected_version, bool) or not isinstance(expected_version, int) or expected_version != self.versions[drone_id]:
            return {"status": "rejected", "reason": "stale version", "version": self.versions[drone_id]}
        if drone_id in self.active:
            old = self.jobs[self.active[drone_id]]
            if old.status in ("queued", "running"):
                if not preempt:
                    return {"status": "rejected", "reason": "aircraft has an active job"}
                self.transition(old, "cancelled", now, "preempted by safe exit")
        self.versions[drone_id] += 1
        job_id = f"job-{len(self.jobs)+1:04d}"
        job = Job(job_id, drone_id, kind, self.versions[drone_id], now, dict(params))
        self.jobs[job_id] = job
        self.active[drone_id] = job_id
        self.transitions.append({"t": now, "job_id": job_id, "status": "queued"})
        return {"status": "accepted", "job_id": job_id, "version": job.version}

    def transition(self, job, status, now, reason=None):
        legal = {"queued": {"running", "cancelled", "failed"},
                 "running": {"succeeded", "failed", "cancelled"}}
        if status not in legal.get(job.status, set()):
            raise ValueError("illegal job state transition")
        job.status, job.reason = status, reason
        if status == "running":
            job.started_at = now
        else:
            job.finished_at = now
        self.transitions.append({"t": now, "job_id": job.job_id, "status": status, "reason": reason})

    def cancel(self, job_id, expected_version, now):
        job = self.jobs.get(job_id)
        if job is None:
            return {"status": "rejected", "reason": "unknown job"}
        if expected_version != self.versions[job.drone_id] or isinstance(expected_version, bool) or not isinstance(expected_version, int):
            return {"status": "rejected", "reason": "stale version"}
        if job.status not in ("queued", "running"):
            return {"status": "rejected", "reason": "job already terminal"}
        self.transition(job, "cancelled", now, "actor cancellation")
        self.versions[job.drone_id] += 1
        return {"status": "accepted", "version": self.versions[job.drone_id]}

    def public(self):
        return [asdict(job) for job in self.jobs.values()]

"""B0 reference policy. Input is exclusively the serialized public stream."""

from __future__ import annotations

from collections import Counter, defaultdict
import math


class ReferencePolicy:
    def __init__(self):
        self.history = defaultdict(list)
        self.seen = set()
        self.reports = {}
        self.report_points = {}
        self.pending_reports = {}
        self.report_aliases = defaultdict(set)
        self.rejected = set()
        self.observed = set()
        self.confirmed = set()
        self.pending = set()
        self.pending_cancellations = {}
        self.calls = 0

    def result(self, name, args, response):
        if "drone_id" in args:
            self.pending.discard(args["drone_id"])
        elif name == "cancel_job" and args["job_id"] in self.pending_cancellations:
            self.pending.discard(self.pending_cancellations.pop(args["job_id"]))
        if name == "submit_or_revise_report":
            rid = args["report_id"]
            self.pending_reports.pop(rid,None)
            aliases = self.report_aliases.pop(rid,set())
            if response.get("status") == "accepted":
                for candidate in aliases:
                    self.reports[candidate] = rid
        if response.get("status") != "accepted":
            return
        if name == "submit_or_revise_report":
            self.reports[args["candidate_id"]] = args["report_id"]
            self.report_points[args["report_id"]] = {"xy":args["estimate_xy"],"object_type":args["object_type"],
                                                   "claimed_class":args["claimed_class"]}
        elif name == "observe_track":
            self.observed.add(args["candidate_id"])

    @staticmethod
    def report_request(obs):
        return {"report_id": "report-"+obs["candidate_id"], "object_type": obs["object_type"],
                "candidate_id": obs["candidate_id"], "measured_at": obs["measured_at"],
                "estimate_xy": obs["estimate_xy"], "claimed_class": obs["estimated_class"],
                "evidence_ids": [obs["evidence_id"]]}

    def decide(self, state):
        for obs in state["observations"]:
            if obs["evidence_id"] not in self.seen:
                self.seen.add(obs["evidence_id"])
                self.history[obs["candidate_id"]].append(obs)
        jobs = state["jobs"]
        for job in jobs:
            candidate = job["params"].get("candidate_id")
            if job["kind"] == "inspect" and job["status"] == "succeeded":
                self.confirmed.add(candidate)
            if job["kind"] == "inspect" and job["status"] == "failed" and candidate not in self.reports:
                self.rejected.add(candidate)
            if job["kind"] == "observe" and job["status"] in ("failed","cancelled"):
                self.observed.discard(candidate)
        commands = []
        for candidate, observations in self.history.items():
            qualified = [o for o in observations if o["sensor_mode"] == "inspect" and o["quality"] >= .8]
            if len(qualified) >= 2 and any(math.dist(qualified[0]["aircraft_xy"], o["aircraft_xy"]) >= 20 for o in qualified[1:]):
                counts = Counter(o["estimated_class"] for o in qualified[-8:])
                winner,count = counts.most_common(1)[0]
                if count <= sum(counts.values())/2:
                    continue
                latest = next(o for o in reversed(qualified) if o["estimated_class"] == winner)
                if winner == "normal":
                    self.rejected.add(candidate)
                elif (candidate not in self.reports and state["report_slots_used"]+len(self.pending_reports)
                      < state["task_card"]["report_budget"]):
                    # Per-aircraft handles are not global identities. Merge
                    # independently confirmed static locations from public
                    # measurements before consuming another report slot.
                    duplicate = next((rid for rid,row in {**self.report_points,**self.pending_reports}.items()
                                      if latest["object_type"] == row["object_type"] == "static"
                                      and math.dist(latest["estimate_xy"],row["xy"]) <= 15),None)
                    if duplicate is not None:
                        if duplicate in self.report_points:
                            self.reports[candidate] = duplicate
                        else:
                            self.report_aliases[duplicate].add(candidate)
                    else:
                        report = self.report_request(latest)
                        self.pending_reports[report["report_id"]] = {"xy":report["estimate_xy"],"object_type":report["object_type"],
                                                                   "claimed_class":report["claimed_class"]}
                        commands.append(("submit_or_revise_report", report))
        for aircraft in state["aircraft"]:
            i = aircraft["drone_id"]
            if i in self.pending or aircraft["retired"] or not aircraft["link_available"]:
                continue
            active = next((j for j in reversed(jobs) if j["drone_id"] == i and j["status"] in ("queued", "running")), None)
            version = aircraft["job_version"]
            if state["sim_time"] >= 470:
                if not active or active["kind"] != "exit":
                    # A terminal exit keeps its physical orbit without reissuing.
                    if any(j["drone_id"] == i and j["kind"] == "exit" and j["status"] == "succeeded" for j in jobs):
                        continue
                    commands.append(("enter_safe_exit", {"drone_id": i, "expected_version": version}))
                    self.pending.add(i)
                continue
            if active and active["kind"] in ("inspect", "observe", "exit"):
                continue
            candidates = []
            for candidate, observations in self.history.items():
                latest = observations[-1]
                if candidate in self.rejected or len(observations) < 2 or latest["estimated_class"] == "normal":
                    continue
                if candidate in self.confirmed and candidate not in self.reports:
                    # Completion telemetry may precede the last camera packet.
                    # Wait for that evidence instead of starting a second job.
                    continue
                if latest["drone_id"] != i or state["sim_time"]-latest["measured_at"] > 30:
                    continue
                if candidate in self.reports:
                    if latest["object_type"] != "dynamic" or candidate in self.observed:
                        continue
                candidates.append((latest["measured_at"], candidate, latest))
            selected = max(candidates, default=None)
            if selected and aircraft["camera_quality"] >= .8:
                if active:
                    commands.append(("cancel_job", {"job_id": active["job_id"], "expected_version": version}))
                    self.pending_cancellations[active["job_id"]] = i
                else:
                    _, candidate, latest = selected
                    rule = "dynamic-inspection" if latest["object_type"] == "dynamic" else next(
                        r["rule_id"] for r in state["task_card"]["rules"] if latest["estimated_class"] in r["classes"])
                    args = {"drone_id": i, "candidate_id": candidate, "expected_version": version,
                            "rule_id": rule, "task_card_version": state["task_card"]["task_card_version"]}
                    if candidate in self.reports:
                        args.update(duration=min(180.0, 470-state["sim_time"]), report_id=self.reports[candidate])
                        commands.append(("observe_track", args))
                    else:
                        commands.append(("inspect_candidate", args))
                self.pending.add(i)
            elif not active:
                commands.append(("assign_survey", {"drone_id": i, "region_id": f"stripe-{i}", "duration": 100.0,
                                                   "expected_version": version, "rule_id": "static-0",
                                                   "task_card_version": state["task_card"]["task_card_version"]}))
                self.pending.add(i)
        self.calls += len(commands)
        return commands

"""Recount saved240Hz executor errors without running a new physical episode."""

import base64
import hashlib
import zlib

import numpy as np


COLUMNS = ["t"]+[f"drone-{i}-{field}" for i in range(4)
    for field in ("xy_error_m","z_m","z_low_m","z_high_m")]


def recount_tracking(record):
    trace = record["execution_tracking_trace"]
    if trace["encoding"]!="base64-zlib-little-endian-float64" or trace["columns"]!=COLUMNS:
        raise ValueError("unsupported physical error trace schema")
    count = record["execution_tracking_240hz"]["physics_samples"]
    if type(count) is not int or not 0<count<=600*240 or trace["rows"]!=count:
        raise ValueError("nonempty complete bounded trace required")
    raw = zlib.decompress(base64.b64decode(trace["data"],validate=True))
    if len(raw)!=count*len(COLUMNS)*8 or hashlib.sha256(raw).hexdigest()!=trace["raw_sha256"]:
        raise ValueError("physical trace bytes/hash mismatch")
    rows = np.frombuffer(raw,dtype='<f8').reshape(count,len(COLUMNS))
    if not np.isfinite(rows).all() or not np.allclose(rows[:,0],np.arange(1,count+1)/240,atol=1e-9,rtol=0):
        raise ValueError("invalid physical trace time or numeric coverage")
    xy,z,low,high = (rows[:,offset::4] for offset in (1,2,3,4))
    if np.any(xy<0) or np.any(low>high):
        raise ValueError("invalid physical trace domains")
    return {"physics_samples":count,"max_horizontal_error_m":float(xy.max()),
        "horizontal_tube_breach_steps":int(np.any(xy>6,axis=1).sum()),
        "altitude_envelope_breach_steps":int(np.any((z<low)|(z>high),axis=1).sum())}
